export function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.heart}"/></svg>`;}
export const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const badge=(text,color='green')=>`<span class="badge ${color}"><span class="status-dot"></span>${h(text)}</span>`;
export const avatar=(initials,color='green',size='')=>`<span class="avatar ${color} ${size}" aria-hidden="true">${h(initials)}</span>`;
export const info=(text,kind='green')=>`<div class="notice ${kind}">${icon(kind==='orange'?'info':'shield')}<div>${text}</div></div>`;
